INSERT INTO admin_audit_log(actor_user_id,action,details,created_at) SELECT id,'fisiologia_sebentas_published','{"batch":"fis1-sebenta-integral-frequency1-2026-10-10","files":7,"integralIncomplete":true,"publicAccess":false}',unixepoch()*1000 FROM users WHERE status='active' AND (commission_position='principal_admin' OR role='admin') AND NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE action='fisiologia_sebentas_published' AND details LIKE '%fis1-sebenta-integral-frequency1-2026-10-10%') ORDER BY CASE WHEN commission_position='principal_admin' THEN 0 ELSE 1 END,created_at LIMIT 1;
